mapper.select:
SELECT f.id,f.feedback_code feedbackCode,f.query_id queryId,f.knowledge_base_id knowledgeBaseId,
  f.actor_user_id actorUserId,f.rating,f.reason_code reasonCode,f.comment,
  f.suggested_answer suggestedAnswer,f.status,f.reviewer_user_id reviewerUserId,
  f.review_note reviewNote,f.reviewed_time reviewedTime,f.created_time createdTime,f.updated_time updatedTime,
  t.original_query question,t.answer,t.trace_id traceId
FROM t_query_feedback f JOIN t_query_trace t ON t.query_id=f.query_id
WHERE f.knowledge_base_id=#{kb}
AND f.status=#{status}
ORDER BY FIELD(f.status,'NEW','IN_REVIEW','ACTION_REQUIRED','RESOLVED','REJECTED'),f.created_time DESC
LIMIT #{limit}
